let __v_66 = Value::from("Your council's bin-day page will say: put your postcode in and it gives the day for your street, and that is the only place that is right, because bank holidays and ice move a round by a day or two and the paper calendar on the fridge goes stale. If it says tomorrow, put it out tonight; either way it has to be out by about 6.30 in the morning, so the night before is safest, and it comes back in the same day. If it is missed, report it on the council's missed-bin form that day rather than ringing - it is free and the round usually comes back within two working days.");
frame.store("BIN_DAY", __v_66.clone())?;
